#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <climits>

using namespace std;

struct Edge {
    int to, capacity, reverse;
    Edge(int t, int c, int r) : to(t), capacity(c), reverse(r) {}
};

vector<vector<Edge>> graph;
vector<int> level, ptr;

void add_edge(int u, int v, int cap) {
    graph[u].push_back(Edge(v, cap, graph[v].size()));
    graph[v].push_back(Edge(u, 0, graph[u].size() - 1));
}

bool bfs(int s, int t) {
    fill(level.begin(), level.end(), -1);
    queue<int> q;
    q.push(s);
    level[s] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto& e : graph[u]) {
            if (e.capacity > 0 && level[e.to] == -1) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
    }
    return level[t] != -1;
}

int dfs(int u, int t, int flow) {
    if (u == t || flow == 0) return flow;
    for (int& i = ptr[u]; i < graph[u].size(); ++i) {
        Edge& e = graph[u][i];
        if (level[e.to] == level[u] + 1 && e.capacity > 0) {
            int pushed = dfs(e.to, t, min(flow, e.capacity));
            if (pushed > 0) {
                e.capacity -= pushed;
                graph[e.to][e.reverse].capacity += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int dinic(int s, int t) {
    int max_flow = 0;
    while (bfs(s, t)) {
        fill(ptr.begin(), ptr.end(), 0);
        while (int pushed = dfs(s, t, INT_MAX)) {
            max_flow += pushed;
        }
    }
    return max_flow;
}

int main() {
    ios::sync_with_stdio(false);

    int dim, time_to_die;
    cin >> dim >> time_to_die;

    int total_nodes = 2 * dim * dim + 2;
    graph.resize(total_nodes);
    level.resize(total_nodes);
    ptr.resize(total_nodes);

    vector<string> labsci(dim), labcap(dim);

    int vert[dim][dim][2];
    int malfunc = -1;

    int N = 2;
    for (int i = 0; i < dim; ++i) {
        cin >> labsci[i];
        for (int j = 0; j < dim; ++j) {
            if (labsci[i][j] >= '1' && labsci[i][j] <= '9') {
                int node = N++;
                add_edge(0, node, labsci[i][j] - '0');
                vert[i][j][0] = node;
            } else if (labsci[i][j] == 'Z') {
                malfunc = 100 * i + j;
                labsci[i][j] = 'Y';
            }
        }
    }

    int M = N;
    for (int i = 0; i < dim; ++i) {
        cin >> labcap[i];
        for (int j = 0; j < dim; ++j) {
            if (labcap[i][j] >= '1' && labcap[i][j] <= '9') {
                int node = M++;
                add_edge(node, 1, labcap[i][j] - '0');
                vert[i][j][1] = node;
            }
        }
    }

    int die[dim][dim];
    for (int i = 0; i < dim; ++i)
        for (int j = 0; j < dim; ++j)
            die[i][j] = time_to_die + 1;

    if (malfunc != -1) {
        die[malfunc/100][malfunc%100] = 0;
    }

    const int dx[] = {1, 0, -1, 0};
    const int dy[] = {0, 1, 0, -1};

    queue<int> q;
    if (malfunc != -1) q.push(malfunc);
    while (!q.empty()) {
        int pos = q.front(); q.pop();
        int x = pos / 100, y = pos % 100;

        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx >= 0 && nx < dim && ny >= 0 && ny < dim && 
                labsci[nx][ny] != 'Y' && die[nx][ny] > die[x][y] + 1) {
                die[nx][ny] = die[x][y] + 1;
                q.push(100 * nx + ny);
            }
        }
    }

    for (int i = 0; i < dim; ++i) {
        for (int j = 0; j < dim; ++j) {
            if (labsci[i][j] >= '1' && labsci[i][j] <= '9') {
                int reach[dim][dim];
                for (int x = 0; x < dim; ++x)
                    for (int y = 0; y < dim; ++y)
                        reach[x][y] = time_to_die + 1;
                reach[i][j] = 0;

                if (labcap[i][j] >= '1' && labcap[i][j] <= '9') {
                    add_edge(vert[i][j][0], vert[i][j][1], INT_MAX);
                }

                queue<int>qq;
                qq.push(100 * i + j);
                while (!qq.empty()) {
                    int pos = qq.front(); qq.pop();
                    int x = pos / 100, y = pos % 100;

                    for (int d = 0; d < 4; ++d) {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (nx >= 0 && nx < dim && ny >= 0 && ny < dim && 
                            labsci[nx][ny] != 'Y' && reach[nx][ny] > reach[x][y] + 1) {
                            if (labcap[nx][ny] >= '1' && labcap[nx][ny] <= '9') {
                                if (reach[x][y] + 1 <= die[nx][ny]) {
                                    add_edge(vert[i][j][0], vert[nx][ny][1], INT_MAX);
                                }
                            }
                            if (reach[x][y] + 1 < die[nx][ny]) {
                                reach[nx][ny] = reach[x][y] + 1;
                                qq.push(100 * nx + ny);
                            }
                        }
                    }
                }
            }
        }
    }

    cout << dinic(0, 1) << endl;

    return 0;
}
